### 2.2 Logger Configuration

```typescript
// src/utils/logger.ts
import pino from 'pino';
import { config } from '../config';

export const logger = pino({
  level: config.LOG_LEVEL,
  base: {
    service: config.SERVICE_NAME,
    version: config.SERVICE_VERSION,
    env: config.NODE_ENV,
  },
  timestamp: pino.stdTimeFunctions.isoTime,
  formatters: {
    level: (label) => ({ level: label }),
  },
  redact: {
    paths: [
      'req.headers.authorization',
      'req.headers.cookie',
      'body.ssn',
      'body.dateOfBirth',
      'body.dob',
      'body.memberId',
      'body.memberNumber',
      'body.npi',
      'body.providerNpi',
      'body.taxId',
      'body.password',
      'body.token',
    ],
    censor: '[REDACTED]',
  },
  serializers: {
    req: pino.stdSerializers.req,
    res: pino.stdSerializers.res,
    err: pino.stdSerializers.err,
  },
});
```

In production (`NODE_ENV=production`), the logger outputs newline-delimited JSON. In development, use `pino-pretty` as a dev-only transform:

```bash
# Local development
npx ts-node-dev src/server.ts | npx pino-pretty
```

Do not use `pino-pretty` in production — it parses and reformats each log line, adding CPU overhead.

