### 2.3 Correlation ID Propagation

Every log entry in a request context **must** include a correlation ID that links all log entries for a single request across services. This is a cross-cutting observability requirement.

The correlation ID is:
- Read from the incoming `X-Correlation-ID` header if present.
- Generated as a UUID v4 if not present in the request.
- Propagated to all downstream service calls as the `X-Correlation-ID` header.

```typescript
// src/api/middleware/correlation-id.middleware.ts
import { Request, Response, NextFunction } from 'express';
import { randomUUID } from 'node:crypto';

declare global {
  namespace Express {
    interface Request {
      correlationId: string;
    }
  }
}

export function correlationIdMiddleware(req: Request, res: Response, next: NextFunction): void {
  const correlationId =
    typeof req.headers['x-correlation-id'] === 'string'
      ? req.headers['x-correlation-id']
      : randomUUID();
  req.correlationId = correlationId;
  res.setHeader('X-Correlation-ID', correlationId);
  next();
}
```

Use `pino-http` to attach the correlation ID to all request-scoped log entries:

```typescript
// src/app.ts
import pinoHttp from 'pino-http';
import { logger } from './utils/logger';

app.use(correlationIdMiddleware);
app.use(
  pinoHttp({
    logger,
    genReqId: (req) => req.correlationId,
    customLogLevel: (_req, res) => {
      if (res.statusCode >= 500) return 'error';
      if (res.statusCode >= 400) return 'warn';
      return 'info';
    },
  })
);
```

