### 4.3 Log Scrubber Middleware

For request bodies that may contain PHI, log a sanitised summary rather than the full body. Define a body sanitiser that returns a version of the object with PHI fields removed:

```typescript
// src/utils/sanitise-log-body.ts
const PHI_FIELDS = new Set([
  'ssn', 'socialsecuritynumber', 'dateofbirth', 'dob',
  'memberid', 'membernumber', 'subscriberid',
  'npi', 'providernpi', 'taxid', 'ein',
  'password', 'token', 'apikey', 'secret',
]);

export function sanitiseForLog(obj: unknown, depth = 0): unknown {
  if (depth > 5 || obj === null || typeof obj !== 'object') return obj;
  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(obj as Record<string, unknown>)) {
    result[key] = PHI_FIELDS.has(key.toLowerCase()) ? '[REDACTED]' : sanitiseForLog(value, depth + 1);
  }
  return result;
}
```

