## 5.0 Process-Level Error Handlers and Graceful Shutdown

All Node.js services **must** register `unhandledRejection` and `uncaughtException` handlers. Refer to STD-TEC-NODE-001 §6.2 for the full required implementation. The required sequence is:

1. Log the error at `error` level with full stack trace and signal name.
2. Emit a `closing` health status so load balancers stop routing new traffic.
3. Call `server.close()` to stop accepting new connections.
4. Allow active requests to drain with a configurable timeout (default 10 seconds).
5. Call `process.exit(1)` — non-zero to trigger container restart.

```typescript
// src/server.ts
import { createServer } from 'node:http';
import { app } from './app';
import { logger } from './utils/logger';
import { config } from './config';

export const server = createServer(app);

let isShuttingDown = false;

export function shutdown(signal: string, error?: unknown): void {
  if (isShuttingDown) return;
  isShuttingDown = true;

  logger.error({ signal, err: error }, 'Graceful shutdown initiated');

  server.close(() => {
    logger.info('All connections drained. Exiting process.');
    process.exit(error !== undefined ? 1 : 0);
  });

  setTimeout(() => {
    logger.error('Drain timeout exceeded. Forcing process exit.');
    process.exit(1);
  }, config.SHUTDOWN_TIMEOUT_MS).unref();
}

process.on('unhandledRejection', (reason) => {
  shutdown('unhandledRejection', reason);
});

process.on('uncaughtException', (error) => {
  shutdown('uncaughtException', error);
});

process.on('SIGTERM', () => {
  logger.info('SIGTERM received');
  shutdown('SIGTERM');
});

process.on('SIGINT', () => {
  logger.info('SIGINT received');
  shutdown('SIGINT');
});

server.listen(config.PORT, () => {
  logger.info({ port: config.PORT }, 'Service listening');
});
```

