### 6.1 Using `unknown` in catch Blocks

TypeScript 4.0+ defaults to typing caught errors as `unknown`. Accessing properties on an `unknown` value requires a type guard. Using `any` in catch blocks is prohibited.

```typescript
// REQUIRED — use unknown and type guard
try {
  await memberService.getById(memberId);
} catch (error: unknown) {
  if (error instanceof AppError) {
    logger.warn({ err: error, code: error.code }, 'Application error');
    res.status(error.statusCode).json({ error: error.message, code: error.code });
    return;
  }
  if (error instanceof Error) {
    logger.error({ err: error }, 'Unexpected error');
  } else {
    logger.error({ err: String(error) }, 'Non-Error thrown');
  }
  next(error);
}

// PROHIBITED — do not use any
} catch (error: any) {
  logger.error(error.message); // type-unsafe
}
```

A utility function avoids repetitive type checking:

```typescript
// src/utils/errors.ts
export function toError(value: unknown): Error {
  if (value instanceof Error) return value;
  return new Error(String(value));
}

export function getErrorMessage(value: unknown): string {
  return toError(value).message;
}
```

