### 6.2 Custom Error Classes

Define a typed error hierarchy for classifying errors at the application boundary:

```typescript
// src/utils/errors.ts

export type ErrorCode =
  | 'VALIDATION_ERROR'
  | 'NOT_FOUND'
  | 'UNAUTHORISED'
  | 'FORBIDDEN'
  | 'UPSTREAM_ERROR'
  | 'INTERNAL_ERROR';

export class AppError extends Error {
  public readonly code: ErrorCode;
  public readonly statusCode: number;
  public readonly isOperational: boolean;

  constructor(message: string, code: ErrorCode, statusCode: number, isOperational = true) {
    super(message);
    this.name = 'AppError';
    this.code = code;
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    Error.captureStackTrace(this, this.constructor);
  }
}

export class ValidationError extends AppError {
  constructor(message: string) {
    super(message, 'VALIDATION_ERROR', 400);
    this.name = 'ValidationError';
  }
}

export class NotFoundError extends AppError {
  constructor(resource: string) {
    super(`${resource} not found`, 'NOT_FOUND', 404);
    this.name = 'NotFoundError';
  }
}

export class UpstreamError extends AppError {
  constructor(upstream: string, message: string) {
    super(`Upstream error from ${upstream}: ${message}`, 'UPSTREAM_ERROR', 502);
    this.name = 'UpstreamError';
  }
}
```

The `isOperational` flag distinguishes expected application errors (validation, not-found) from unexpected programmer errors. Non-operational errors should trigger graceful shutdown.

