## 8.0 Express Error Middleware

A centralised Express error handler middleware must be registered as the last middleware in the application:

```typescript
// src/api/middleware/error-handler.middleware.ts
import { Request, Response, NextFunction } from 'express';
import { logger } from '../../utils/logger';
import { AppError } from '../../utils/errors';

export function errorHandlerMiddleware(
  error: unknown,
  req: Request,
  res: Response,
  _next: NextFunction
): void {
  const correlationId = req.correlationId;
  const timestamp = new Date().toISOString();

  if (error instanceof AppError) {
    if (error.statusCode >= 500) {
      logger.error({ err: error, correlationId }, 'Operational server error');
    } else {
      logger.warn({ err: error, correlationId }, 'Application error');
    }
    res.status(error.statusCode).json({
      error: {
        code: error.code,
        message: error.message,
        correlationId,
        timestamp,
      },
    });
    return;
  }

  // Unknown / programmer errors
  logger.error({ err: error, correlationId }, 'Unhandled error in request pipeline');
  res.status(500).json({
    error: {
      code: 'INTERNAL_ERROR',
      message: 'An unexpected error occurred.',
      correlationId,
      timestamp,
    },
  });
}
```

```typescript
// src/app.ts — register last
import { errorHandlerMiddleware } from './api/middleware/error-handler.middleware';
// ... routes ...
app.use(errorHandlerMiddleware);
```
